fn sumEven(nums: [int]) -> int {
    var total = 0
    for x in nums {
        if x % 2 == 0 { total += x }
    }
    total
}

fn countVowels(s: str) -> int {
    var n = 0
    for c in s {
        if c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' { n += 1 }
    }
    n
}

fn isPalindrome(s: str) -> bool {
    var i = 0
    var j = s.len() - 1
    while i < j {
        if s[i] != s[j] { return false }
        i += 1
        j -= 1
    }
    true
}

fn reverseWords(s: str) -> str {
    s.split(" ").reverse().join(" ")
}

fn factorial(n: int) -> int {
    var result = 1
    for i in 2..=n {
        result *= i
    }
    result
}

fn isPrime(n: int) -> bool {
    if n < 2 { return false }
    if n < 4 { return true }
    if n % 2 == 0 { return false }
    var i = 3
    while i * i <= n {
        if n % i == 0 { return false }
        i += 2
    }
    true
}

fn fibonacci(n: int) -> int {
    var a = 0
    var b = 1
    for _ in 0..n {
        var t = a + b
        a = b
        b = t
    }
    a
}

fn maxOfList(nums: [int]) -> int {
