}

fn collatzSteps(n: int) -> int {
    var x = n
    var steps = 0
    while x != 1 {
        if x % 2 == 0 { x /= 2 } else { x = 3 * x + 1 }
        steps += 1
    }
    steps
}

fn runLengthEncode(s: str) -> str {
    var out = ""
    var i = 0
    while i < s.len() {
        var c = s[i]
        var count = 0
        while i < s.len() && s[i] == c {
            count += 1
            i += 1
        }
        out += strFromByte(c) + str(count)
    }
    out
}

fn balancedParens(s: str) -> bool {
    var depth = 0
    for c in s {
        if c == '(' { depth += 1 }
        else if c == ')' {
            depth -= 1
            if depth < 0 { return false }
        }
    }
    depth == 0
}

fn longestRun(nums: [int]) -> int {
    var best = 0
    var cur = 0
    var prev = 0
    var first = true
    for x in nums {
        if first {
            cur = 1
            prev = x
            first = false
        } else if x == prev {
            cur += 1
        } else {
            cur = 1
            prev = x
        }
        if cur > best { best = cur }
    }
    best
}

fn mergeSorted(a: [int], b: [int]) -> [int] {
    var out: [int] = []
    var i = 0
    var j = 0
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i])
            i += 1
        } else {
            out.push(b[j])
            j += 1
        }
    }
    while i < a.len() { out.push(a[i]); i += 1 }
    while j < b.len() { out.push(b[j]); j += 1 }
    out
}

