fn caesarShift(s: str, k: int) -> str {
    var out = ""
    for c in s {
        if c >= 'a' && c <= 'z' {
            var code = int(c) - int('a') + k
            if code >= 26 { code -= 26 }
            out += strFromByte(code + int('a'))
        } else {
            out += c
        }
    }
    out
}

fn caesarShift(s: str, k: int) -> str {
    var out = ""
    for i in 0..s.len() {
        var b = s[i]
        if b >= int('a') && b <= int('z') {
            var code = b - int('a') + k
            if code >= 26 { code -= 26 }
            out += strFromByte(code + int('a'))
        } else {
            out += strFromByte(b)
        }
    }
    out
}

fn toBinary(n: int) -> str {
    if n == 0 { return "0" }
    var s = ""
    var x = n
    while x > 0 {
        s = strFromByte(int('0') + int(x % 2)) + s
        x = x / 2
    }
    s
}

fn digitSum(n: int) -> int {
    var total = 0
    var x = n
    while x > 0 {
        total += x % 10
        x /= 10
    }
    total
}

fn twoSum(nums: [int], target: int) -> [int] {
    for i in 0..nums.len() {
        for j in i + 1..nums.len() {
            if nums[i] + nums[j] == target {
                return [i, j]
            }
        }
    }
    [-1, -1]
}

fn maxSubarraySum(nums: [int]) -> int {
    var best = nums[0]
    var cur = nums[0]
    for i in 1..nums.len() {
        cur = max(cur + nums[i], nums[i])
        best = max(best, cur)
    }
    best
}

fn primeFactors(n: int) -> [int] {
    var result: [int] = []
    var m = n
    var d = 2
    while d * d <= m {
        while m % d == 0 {
            result.push(d)
            m /= d
        }
        d += 1
    }
    if m > 1 { result.push(m) }
    result
}

