fn longestCommonPrefix(words: [str]) -> str {
    if words.len() == 0 { return "" }
    var prefix = words[0]
    for w in words {
        var n = min(prefix.len(), w.len())
        var i = 0
        while i < n && prefix[i] == w[i] {
            i += 1
        }
        prefix = prefix[0..i]
    }
    prefix
}

fn rotateLeft(nums: [int], k: int) -> [int] {
    var n = nums.len()
    if n == 0 { return [] }
    var kk = k % n
    var res: [int] = []
    for i in 0..n {
        res.push(nums[(i + kk) % n])
    }
    res
}

