fn isAnagram(a: str, b: str) -> bool {
    if a.len() != b.len() { return false }
    var counts: Map<str, int> = mapNew()
    for c in a { counts[c] += 1 }
    for c in b { counts[c] -= 1 }
    for k in counts.keys() {
        if counts[k] != 0 { return false }
    }
    true
}

fn secondLargest(nums: [int]) -> int {
    var seen: Set<int> = setNew()
    var vals: [int] = []
    for x in nums {
        if !seen.has(x) {
            seen.add(x)
            vals.push(x)
        }
    }
    if vals.len() < 2 { return -1 }
    vals.sort()
    vals[vals.len() - 2]
}

fn pascalRow(n: int) -> [int] {
    var row: [int] = [1]
    for i in 0..n {
        var next: [int] = [1]
        for j in 0..row.len() - 1 {
            next.push(row[j] + row[j + 1])
        }
        next.push(1)
        row = next
    }
    row
}

