fn mostFrequent(nums: [int]) -> int {
    var counts: Map<int, int> = mapNew()
    for x in nums { counts[x] += 1 }
    var best = nums[0]
    var bestCount = counts[best]
    for x in nums {
        if counts[x] > bestCount || (counts[x] == bestCount && x < best) {
            best = x
            bestCount = counts[x]
        }
    }
    best
}

fn collapseSpaces(s: str) -> str {
    var out = ""
    var prevSpace = true
    for c in s {
        if c == ' ' {
            if !prevSpace { out += " " }
            prevSpace = true
        } else {
            out += c
            prevSpace = false
        }
    }
    if prevSpace && out.len() > 0 {
        out = out[0..out.len() - 1]
    }
    out
}

