fn countInversions(nums: [int]) -> int {
    fn mergeCount(a: [int], b: [int]) -> (int, [int]) {
        var count = 0
        var out: [int] = []
        var i = 0
        var j = 0
        while i < a.len() && j < b.len() {
            if a[i] <= b[j] {
                out.push(a[i])
                i += 1
            } else {
                out.push(b[j])
                j += 1
                count += a.len() - i
            }
        }
        while i < a.len() { out.push(a[i]); i += 1 }
        while j < b.len() { out.push(b[j]); j += 1 }
        (count, out)
    }
    fn sortCount(a: [int]) -> (int, [int]) {
        if a.len() <= 1 {
            (0, a)
        } else {
            let mid = a.len() / 2
            let (c1, left) = sortCount(a[0..mid])
            let (c2, right) = sortCount(a[mid..a.len()])
            let (c3, merged) = mergeCount(left, right)
            (c1 + c2 + c3, merged)
        }
    }
    sortCount(nums)[0]
}

fn countInversions(nums: [int]) -> int {
    var total = 0
    var width = 1
    var n = nums.len()
    var work: [int] = nums
    var tmp: [int] = repeat(0, n)
    while width < n {
        var i = 0
        while i < n {
            let mid = min(i + width, n)
            let hi = min(i + 2 * width, n)
            var a = i
            var b = mid
            var k = i
            while a < mid && b < hi {
                if work[a] <= work[b] {
                    tmp[k] = work[a]
                    a += 1
                } else {
                    tmp[k] = work[b]
                    b += 1
                    total += mid - a
                }
                k += 1
            }
            while a < mid { tmp[k] = work[a]; a += 1; k += 1 }
            while b < hi { tmp[k] = work[b]; b += 1; k += 1 }
            var t = i
            while t < hi { work[t] = tmp[t]; t += 1 }
            i += 2 * width
        }
        width *= 2
    }
    total
}

fn toHex(n: int) -> str {
    if n == 0 { return "0" }
    var digits = "0123456789abcdef"
    var res = ""
    var x = n
    while x > 0 {
        res = strFromByte(digits[x % 16]) + res
        x = x / 16
    }
    res
}

fn wordsStartingWithVowel(words: [str]) -> [str] {
    words.filter(|w| w.len() > 0 && "aeiou".contains(w[0..1]))
}

fn integerSqrt(n: int) -> int {
    var lo = 0
    var hi = n
    while lo < hi {
        var mid = (lo + hi + 1) / 2
        if mid <= n / mid {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    lo
}

fn interleave(a: [int], b: [int]) -> [int] {
    var out: [int] = []
    var n = min(a.len(), b.len())
    for i in 0..n {
        out.push(a[i])
        out.push(b[i])
    }
    for x in a[n..a.len()] { out.push(x) }
    for x in b[n..b.len()] { out.push(x) }
    out
}

fn charCodeSum(s: str) -> int {
    var total = 0
    for c in s {
        total += c[0]
    }
    total
}

fn joinUppercase(words: [str], sep: str) -> str {
    words.map(|w| w.upper()).join(sep)
}

fn bestProfit(prices: [int]) -> int {
    var best = 0
    var lowest = prices[0]
    for i in 1..prices.len() {
        best = max(best, prices[i] - lowest)
        lowest = min(lowest, prices[i])
    }
    best
}

fn missingNumber(nums: [int]) -> int {
    var total = 0
    for x in nums { total += x }
    var n = nums.len()
    n * (n + 1) / 2 - total
}

fn toRoman(n: int) -> str {
    var vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    var syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    var res = ""
    var x = n
    for i in 0..vals.len() {
        while x >= vals[i] {
            res += syms[i]
            x -= vals[i]
        }
    }
    res
}

fn average(nums: [int]) -> float {
    float(nums.sum()) / float(nums.len())
}

fn celsiusToFahrenheit(c: float) -> float {
    c * 9.0 / 5.0 + 32.0
}

fn countWords(s: str) -> int {
